	client->difffilelen = 0;
	if(client->server->flags & F_SPARSE) {
		/* Create a sparse file as large as the export, so that
		 * each block can be stored at its own offset */
		if(ftruncate(client->difffile, client->exportsize) == -1) {
			err_nonfatal("Could not resize diff file: %m");
			close(client->difffile);
			client->difffile = -1;
