void daemonize() {
        pid_t child=fork();
        if(child < 0) {
		err("fork");
	} else if(child > 0) {
                exit(EXIT_SUCCESS);
	} else {
                if(setsid() < 0) {
                        err("setsid");
                }
        }
        if(chdir("/")<0) {
                err("chdir");
        }
	if(!*pidfname) {
		strncpy(pidfname, "/var/run/nbd-server.pid", 255);
	}
        int newfd;
        if((newfd = open("/dev/null", O_RDWR)) < 0) {
                err("open");
        }
        if(dup2(0, newfd) < 0) {
                err("dup2 stdin");
        }
        if(dup2(1, newfd) < 0) {
                err("dup2 stdout");
        }
        if(dup2(2, newfd) < 0) {
                err("dup2 stderr");
        }
        child=fork();
        if(child < 0) {
                err("fork");
        } else if(child > 0) {
                exit(EXIT_SUCCESS);
