        g_free(*(void**) p);
}
#define _cleanup_g_free_ _cleanup_(g_freep)
#define DEFINE_TRIVIAL_CLEANUP_FUNC(type, func)	\
        static inline void func##p(type *p) {	\
                if (*p)				\
                        func(*p);		\
