/*
 * Throwaway client: exercise WRITE_ZEROES, FLUSH and TRIM against a
 * copy-on-write export, then verify contents. Based on cow-client.c.
 */
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#include "config.h"
#include "lfs.h"

#define MY_NAME "cow-extra"
#include "cliserv.h"

#define DEVICESIZE (1024 * 1024)

static void fail(const char *msg) {
	fprintf(stderr, "cow-extra: %s\n", msg);
	exit(1);
}

static unsigned char pattern_byte(uint64_t off) {
	return (off * 7 + 13) & 0xff;
}

static int connect_tcp(const char *host, const char *port) {
	struct addrinfo hints, *res;
	int sock, e;
	memset(&hints, 0, sizeof(hints));
	hints.ai_family = AF_UNSPEC;
	hints.ai_socktype = SOCK_STREAM;
	if((e = getaddrinfo(host, port, &hints, &res))) {
		fail("getaddrinfo");
	}
	sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
	if(connect(sock, res->ai_addr, res->ai_addrlen) < 0) {
		fail("could not connect");
	}
	freeaddrinfo(res);
	return sock;
}

static void negotiate_go(int sock, const char *exportname) {
	char init_passwd[8];
	uint64_t magic;
	uint16_t sflags;
	uint32_t cflags, namelen, optlen, opt, type, len;
	uint16_t n_requests;
	struct {
		uint64_t magic;
		uint32_t opt;
		uint32_t len;
	} __attribute__((packed)) optreq;
	struct {
		uint64_t magic;
		uint32_t opt;
		uint32_t type;
		uint32_t len;
	} __attribute__((packed)) optrep;
	char scratch[4096];

	if(readit(sock, init_passwd, 8) < 0) fail("read magic");
	if(memcmp(init_passwd, INIT_PASSWD, 8) != 0) fail("magic mismatch");
	if(readit(sock, &magic, 8) < 0) fail("read opts magic");
	if(ntohll(magic) != 0x49484156454F5054LL) fail("opts magic mismatch");
	if(readit(sock, &sflags, 2) < 0) fail("read handshake flags");
	cflags = htonl(NBD_FLAG_C_FIXED_NEWSTYLE | NBD_FLAG_C_NO_ZEROES);
	if(writeit(sock, &cflags, 4) < 0) fail("send client flags");

	namelen = strlen(exportname);
	n_requests = 0;
	optlen = namelen + sizeof(namelen) + sizeof(n_requests);
	optreq.magic = htonll(0x49484156454F5054LL);
	optreq.opt = htonl(NBD_OPT_GO);
	optreq.len = htonl(optlen);
	namelen = htonl(namelen);
	n_requests = htons(n_requests);
	if(writeit(sock, &optreq, sizeof(optreq)) < 0) fail("send optreq");
	if(writeit(sock, &namelen, sizeof(namelen)) < 0) fail("send namelen");
	if(writeit(sock, exportname, ntohl(namelen)) < 0) fail("send name");
	if(writeit(sock, &n_requests, sizeof(n_requests)) < 0) fail("send nreq");
	while(1) {
		if(readit(sock, &optrep, sizeof(optrep)) < 0) fail("read reply");
		if(ntohll(optrep.magic) != NBD_OPT_REPLY_MAGIC) fail("reply magic");
		type = ntohl(optrep.type);
		len = ntohl(optrep.len);
		if(len > sizeof(scratch)) fail("reply too long");
		if(readit(sock, scratch, len) < 0) fail("read reply data");
		if(type & NBD_REP_FLAG_ERROR) fail("error reply");
		if(type == NBD_REP_ACK) return;
	}
}

static int do_io(int sock, uint32_t cmd, uint64_t from, unsigned char *buf,
		 uint32_t len, uint32_t *rerror) {
	struct nbd_request req;
	struct nbd_reply rep;
	static uint64_t cookie = 0;

	req.magic = htonl(NBD_REQUEST_MAGIC);
	req.type = htonl(cmd);
	req.cookie = htonll(++cookie);
	req.from = htonll(from);
	req.len = htonl(len);
	if(writeit(sock, &req, sizeof(req)) < 0) return -1;
	if(cmd == NBD_CMD_WRITE && writeit(sock, buf, len) < 0) return -1;
	if(readit(sock, &rep, sizeof(rep)) < 0) return -1;
	if(rep.magic != htonl(NBD_REPLY_MAGIC)) fail("reply magic mismatch");
	if(rep.cookie != req.cookie) fail("cookie mismatch");
	*rerror = ntohl(rep.error);
	if(*rerror != 0) return 0;
	if(cmd == NBD_CMD_READ && readit(sock, buf, len) < 0) return -1;
	return 0;
}

int main(int argc, char *argv[]) {
	unsigned char buf[65536];
	unsigned char zeros[8192];
	uint32_t error;
	uint64_t off;
	int i, sock;

	if(argc != 5) {
		fprintf(stderr, "usage: cow-extra <host> <port> <export> <sparse|plain>\n");
		return 1;
	}
	memset(zeros, 0, sizeof(zeros));
	sock = connect_tcp(argv[1], argv[2]);
	negotiate_go(sock, argv[3]);

	/* WRITE_ZEROES 8192 bytes at offset 8192 */
	if(do_io(sock, NBD_CMD_WRITE_ZEROES, 8192, NULL, 8192, &error) < 0)
		fail("write_zeroes failed");
	if(error) { fprintf(stderr, "write_zeroes error %u\n", error); return 1; }

	/* FLUSH must succeed */
	if(do_io(sock, NBD_CMD_FLUSH, 0, NULL, 0, &error) < 0)
		fail("flush failed");
	if(error) { fprintf(stderr, "flush error %u\n", error); return 1; }

	/* TRIM must succeed (no-op on cow, but must not error) */
	if(do_io(sock, NBD_CMD_TRIM, 16384, NULL, 4096, &error) < 0)
		fail("trim failed");
	if(error) { fprintf(stderr, "trim error %u\n", error); return 1; }

	/* write 0xEE over the trimmed region to force COW of that block */
	memset(buf, 0xEE, 4096);
	if(do_io(sock, NBD_CMD_WRITE, 16384, buf, 4096, &error) < 0)
		fail("write failed");
	if(error) { fprintf(stderr, "write error %u\n", error); return 1; }

	/* verify whole export */
	for(off = 0; off < DEVICESIZE; off += sizeof(buf)) {
		if(do_io(sock, NBD_CMD_READ, off, buf, sizeof(buf), &error) < 0)
			fail("read failed");
		if(error) { fprintf(stderr, "read error %u at %llu\n", error,
				    (unsigned long long)off); return 1; }
		for(i = 0; i < (int)sizeof(buf); i++) {
			unsigned char want;
			uint64_t p = off + i;
			if(p >= 8192 && p < 16384)
				want = 0; /* write_zeroes region */
			else if(p >= 16384 && p < 20480)
				want = 0xEE; /* overwritten region */
			else
				want = pattern_byte(p);
			if(buf[i] != want) {
				fprintf(stderr, "mismatch at %llu: got %02x want %02x\n",
					(unsigned long long)p, buf[i], want);
				return 1;
			}
		}
	}
	printf("cow-extra (%s): all checks passed\n", argv[4]);
	close(sock);
	return 0;
}

