	for(off = 0; off < DEVICESIZE; off += sizeof(buf)) {
		if(do_io(sock, NBD_CMD_READ, off, buf, sizeof(buf), &error) < 0)
			fail("read failed");
		if(error) { fprintf(stderr, "read error %u at %llu\n", error,
				    (unsigned long long)off); return 1; }
		for(i = 0; i < (int)sizeof(buf); i++) {
			unsigned char want;
			uint64_t p = off + i;
