/**
 * Tear down copy-on-write: remove the diff file, so that the data
 * written during the connection is lost and the master file is left
 * unmodified. Safe to call for clients without a diff file.
 *
 * @param client the client for which to remove the diff file
 **/
static void cleanup_cow(CLIENT* client) {
	if(!client->difffilename) {
		return;
	}
	DEBUG("Removing diff file %s\n", client->difffilename);
	if(client->difffile != -1) {
		close(client->difffile);
		client->difffile = -1;
	}
	unlink(client->difffilename);
	g_free(client->difffilename);
	client->difffilename = NULL;
	if(client->difmap) {
		g_array_free(client->difmap, TRUE);
		client->difmap = NULL;
	}
	client->difffilelen = 0;
	pthread_mutex_destroy(&(client->difflock));
}

/**
 * Get the offset of a block in the diff file.
 *
 * @param client the client whose diff file is consulted
 * @param block the block number, in units of DIFFPAGESIZE bytes
 * @return the offset in the diff file where the block is stored, or
 * -1 if the block is not present in the diff file
 **/
static off_t diffmap_get(CLIENT* client, uint64_t block) {
	if(client->difmap == NULL || block >= client->difmap->len) {
		return -1;
	}
	return g_array_index(client->difmap, off_t, block);
}

/**
 * Read the original content of a block from the master file.
 *
 * @param client The client whose master file is read
 * @param block The block number, in units of DIFFPAGESIZE bytes
 * @param buf A buffer to read into
 * @param len The size of buf, at most DIFFPAGESIZE
 * @return 0 on success, nonzero on failure
 **/
static int expcowread_master(CLIENT *client, uint64_t block, char *buf, size_t len) {
	off_t a = block * DIFFPAGESIZE;
	ssize_t ret;

	while(len > 0) {
		if((ret = rawexpread(a, buf, len, client)) <= 0) {
			return 1;
		}
		a += ret;
		buf += ret;
		len -= ret;
	}
	return 0;
}

/**
 * Call pwrite repeatedly, until all data has been written to the diff
 * file.
 *
 * @param client The client whose diff file is written
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param pos The offset in the diff file where the write should start
 * @return 0 on success, nonzero on failure
 **/
static int expcowwrite_diff(CLIENT *client, const char *buf, size_t len, off_t pos) {
	ssize_t ret;

	while(len > 0) {
		if((ret = pwrite(client->difffile, buf, len, pos)) <= 0) {
			return 1;
		}
		pos += ret;
		buf += ret;
		len -= ret;
	}
	return 0;
}

/**
 * Write an amount of bytes at a given offset to the diff file of a
 * copy-on-write export. Blocks that are not yet present in the diff
 * file are copied there from the master file first, so that the parts
 * of a block that are not overwritten can still be read back.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're going to write for.
 * @param fua Flag to indicate 'Force Unit Access'
 * @return 0 on success, nonzero on failure
 **/
int expcowwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	while(len > 0) {
		uint64_t block = a / DIFFPAGESIZE;
		size_t chunk = DIFFPAGESIZE - (a % DIFFPAGESIZE);
		off_t pos;
		ssize_t ret;

		if(chunk > len) {
			chunk = len;
		}
		pthread_mutex_lock(&(client->difflock));
		pos = diffmap_get(client, block);
		if(pos == -1) {
			char orig[DIFFPAGESIZE];
			size_t blocklen = DIFFPAGESIZE;
			off_t blockend = block * DIFFPAGESIZE + DIFFPAGESIZE;

			if(client->exportsize < blockend) {
				blocklen = client->exportsize - block * DIFFPAGESIZE;
			}
			if(client->server->flags & F_SPARSE) {
				pos = block * DIFFPAGESIZE;
			} else {
				pos = client->difffilelen;
				client->difffilelen += DIFFPAGESIZE;
			}
			/* Copy the block's original content from the
			 * master file, so that reads of the parts of
			 * the block that are not overwritten keep
			 * returning the master's data */
			if(expcowread_master(client, block, orig, blocklen) ||
			   expcowwrite_diff(client, orig, blocklen, pos)) {
				pthread_mutex_unlock(&(client->difflock));
				return 1;
			}
			g_array_index(client->difmap, off_t, block) = pos;
		}
		DEBUG("(COW WRITE to fd %d offset %llu len %u fua %d), ", client->difffile, (unsigned long long)(pos + (a % DIFFPAGESIZE)), (unsigned int)chunk, fua);
		ret = pwrite(client->difffile, buf, chunk, pos + (a % DIFFPAGESIZE));
		pthread_mutex_unlock(&(client->difflock));
		if(ret <= 0) {
			return 1;
		}
		a += ret;
		buf += ret;
		len -= ret;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if(fua) {
		fdatasync(client->difffile);
	}
	return 0;
}

/**
 * Read an amount of bytes at a given offset from a copy-on-write
 * export. Blocks present in the diff file are read from there,
 * everything else is read from the master file. The read may not
 * cross a block boundary.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf, at most the remainder of the block
 * starting at a
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
ssize_t rawexpcowread(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t pos;
	ssize_t retval;

	pthread_mutex_lock(&(client->difflock));
	pos = diffmap_get(client, a / DIFFPAGESIZE);
	if(pos == -1) {
		pthread_mutex_unlock(&(client->difflock));
		return rawexpread(a, buf, len, client);
	}
	DEBUG("(COW READ from fd %d offset %llu len %u), ", client->difffile, (unsigned long long)(pos + (a % DIFFPAGESIZE)), (unsigned int)len);
	retval = pread(client->difffile, buf, len, pos + (a % DIFFPAGESIZE));
	pthread_mutex_unlock(&(client->difflock));
	return retval;
}

/**
 * Call rawexpcowread repeatedly until all data has been read.
 * @return 0 on success, nonzero on failure
 **/
int expcowread(READ_CTX *ctx, CLIENT *client) {
	ssize_t ret=0;

	char *buf;

	while(ctx->current_len > 0) {
		off_t a = (off_t)ctx->req->from + (off_t)ctx->current_offset;
		size_t len = ctx->current_len;
		size_t chunk = DIFFPAGESIZE - (a % DIFFPAGESIZE);

		if(len > chunk) {
			len = chunk;
		}
		buf = find_read_buf(ctx);
		if((ret = rawexpcowread(a, buf, len, client)) <= 0) {
			break;
		}
		confirm_read(client, ctx, ret);
		ctx->current_offset += ret;
		ctx->current_len -= ret;
	}
	return (ret < 0 || ctx->current_len != 0);
}

/**
 * Read an amount of bytes at a given offset from the right file.
 * @param ctx The read context
 * @param client The client we're going to read for
 * @return 0 on success, nonzero on failure
 **/
int expread(READ_CTX *ctx, CLIENT *client) {
	off_t a = (off_t)ctx->current_offset + (off_t)ctx->req->from;
	size_t len = (size_t) ctx->req->len;

	DEBUG("Asked to read %u bytes at %llu.\n", (unsigned int)len, (unsigned long long)a);

	if (client->server->flags & F_COPYONWRITE)
		return expcowread(ctx, client);

	return(rawexpread_fully(ctx, client));
}

/**
 * Write an amount of bytes at a given offset to the right file.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're going to write for.
 * @param fua Flag to indicate 'Force Unit Access'
 * @return 0 on success, nonzero on failure
 **/
int expwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	DEBUG("Asked to write %u bytes at %llu.\n", (unsigned int)len, (unsigned long long)a);

	if (client->server->flags & F_COPYONWRITE)
		return expcowwrite(a, buf, len, client, fua);

	return(rawexpwrite_fully(a, buf, len, client, fua));
}

